extract_daily_layers <- function(nc_file, expected_variable="2m_temperature") read_era5_daily_layers(nc_file)
standardize_daily_raster <- function(source,template,boundary=NULL,resampling_method="bilinear",mask_to_boundary=FALSE,mask_to_template=TRUE) { if(!requireNamespace("terra",quietly=TRUE))stop("terra is required");out<-terra::project(source,template,method=resampling_method);if(mask_to_template)out<-terra::mask(out,template);if(mask_to_boundary&&!is.null(boundary))out<-terra::mask(out,terra::vect(boundary));out }
process_downloaded_mintemp <- function(raw_files,daily_dir,template_path,bbox_path,config,overwrite_dates=NULL,expected_dates=NULL,run_dir=NULL) { fs::dir_create(daily_dir,recurse=TRUE);template<-terra::rast(template_path);before<-template_fingerprint(template);boundary<-if(isTRUE(config$spatial$mask_to_boundary))sf::st_read(bbox_path,quiet=TRUE)else NULL;written<-character();reused<-character();replaced<-character();failed<-character();readers<-list();if(!length(raw_files)&&!is.null(expected_dates)){existing_inv<-inventory_daily_products(daily_dir,config$project$output_prefix,template_path,TRUE,config);reused<-existing_inv$path[existing_inv$observed_valid%in%TRUE & existing_inv$date%in%as.Date(expected_dates)]};for(f in raw_files){x<-tryCatch(read_era5_daily_layers(f,expected_dates=expected_dates),error=function(e){failed<<-c(f,failed);NULL});if(is.null(x))next;readers[[f]]<-list(reader_used=x$reader_used,source_format=x$source_format,dates=x$dates,temperature_variable=x$temperature_variable%||%NA);for(i in seq_along(x$dates)){d<-x$dates[i];if(!is.null(expected_dates)&&!(d%in%as.Date(expected_dates)))next;out<-file.path(daily_dir,format_daily_filename(config$project$output_prefix,d));existed_before<-file.exists(out);valid_before<-FALSE;if(existed_before){vr0<-validate_daily_output(out,d,template,config);valid_before<-isTRUE(vr0$valid);if(valid_before&&is.null(overwrite_dates)){if(!out%in%reused)reused<-c(reused,out);next}};if(!is.null(overwrite_dates)&&!(d%in%as.Date(overwrite_dates)))next;z<-standardize_daily_raster(x$rasters[[i]],template,boundary,config$processing$resampling_method,isTRUE(config$spatial$mask_to_boundary),isTRUE(config$spatial$mask_to_template));vr<-validate_raster_against_template(z,template,c(config$validation$minimum_celsius,config$validation$maximum_celsius),TRUE);coverage<-tryCatch(validate_template_coverage(z,template,isTRUE(config$spatial$require_complete_template_coverage %||% TRUE),if(isTRUE(config$spatial$write_coverage_diagnostics)&&!is.null(run_dir))file.path(run_dir,"diagnostics","coverage") else NULL,d),error=function(e)e);if(!vr$valid||inherits(coverage,"error")){failed<-c(failed,out);next};tmp<-paste0(out,".tmp.tif");terra::writeRaster(z,tmp,overwrite=TRUE,wopt=list(datatype=config$processing$datatype,gdal=c("COMPRESS=DEFLATE","PREDICTOR=3","TILED=YES"),NAflag=config$processing$naflag));if(file.exists(out))unlink(out);file.rename(tmp,out);est<-file.path(daily_dir,format_daily_filename(config$project$output_prefix,d,TRUE));if(file.exists(est)&&isTRUE(config$processing$delete_replaced_estimates))unlink(est);if(existed_before&&!valid_before)replaced<-c(replaced,out) else written<-c(written,out)}};if(!identical(before,template_fingerprint(template)))stop("Template fingerprint changed during processing");stopifnot(length(intersect(written,reused))==0L,length(intersect(written,replaced))==0L,length(intersect(reused,replaced))==0L);list(written=written,reused=reused,replaced=replaced,failed=failed,readers=readers) }
